import { Abilities } from './abilities';
import { Chat } from './chat';
import { Hero } from './hero';
import { PointBackdrop } from './point-backdrop';
import { POINT_STOPS } from './point-stops';

export default function Heroes13() {
  return (
    <div className='relative isolate flex min-h-screen flex-col'>
      <PointBackdrop stops={POINT_STOPS} />
      <main className='relative z-10 flex-1'>
        <Hero />
        <Chat />
        <Abilities />
      </main>
    </div>
  );
}

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import { DraftDemo } from './ability-draft';
import { NotesDemo } from './ability-notes';
import { PlanDemo } from './ability-plan';
import {
  ABILITIES,
  ABILITIES_ANCHOR,
  ABILITIES_SECTION,
  type AbilityId,
} from './data';

const DEMOS: Record<AbilityId, () => React.ReactNode> = {
  plan: PlanDemo,
  draft: DraftDemo,
  promises: NotesDemo,
};

function isMediaFirst(index: number) {
  return index % 2 === 1;
}

function AbilityDemo({ id }: { id: AbilityId }) {
  const Demo = DEMOS[id];

  return (
    <div className='bg-foreground/[0.03] flex min-h-72 items-center justify-center rounded-2xl p-4 sm:p-10'>
      <Demo />
    </div>
  );
}

export function Abilities() {
  return (
    <section
      id={ABILITIES_ANCHOR}
      className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'
    >
      <div className='mx-auto flex max-w-6xl flex-col gap-14 sm:gap-20'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {ABILITIES_SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {ABILITIES_SECTION.description}
          </p>
        </div>
        <ul className='flex flex-col gap-16 sm:gap-24'>
          {ABILITIES.map((ability, index) => (
            <li
              key={ability.id}
              className='grid grid-cols-1 items-center gap-8 lg:grid-cols-2 lg:gap-16'
            >
              <div className='flex flex-col items-start gap-4'>
                <h3 className='text-xl font-semibold text-balance'>
                  {ability.title}
                </h3>
                <p className='text-muted-foreground max-w-md text-sm leading-relaxed text-pretty'>
                  {ability.description}
                </p>
                <Button
                  variant='link'
                  className='h-auto px-0'
                  nativeButton={false}
                  render={<a href='#' />}
                >
                  {ability.linkLabel}
                  <ArrowRightIcon className='size-3.5' />
                </Button>
              </div>
              <div className={cn(isMediaFirst(index) && 'lg:order-first')}>
                <AbilityDemo id={ability.id} />
              </div>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

'use client';

import { useEffect, useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  hold,
  pressedSolidOf,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { RotateCcwIcon } from '@/registry/ndeko/lib/icons';
import { wordsOf } from '@/registry/ndeko/lib/words';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { StreamedText, StreamedWords } from '@/registry/ndeko/ui/streamed-text';

import { ASSISTANT, DRAFT_REPLY, INCOMING } from './data';
import { useRestingState } from './use-resting-state';

type DraftStage = 'reading' | 'drafting' | 'ready' | 'sent';

const WORD_MS = 45;

const READING_MS = 1300;

const DRAFT_WORDS = wordsOf(DRAFT_REPLY);

const DRAFT_MS = DRAFT_WORDS.length * WORD_MS + 500;

const SEND_AFTER_MS = READING_MS + DRAFT_MS + 1200;

function statusWordOf(stage: DraftStage) {
  if (stage === 'reading') {
    return 'Reading the message';
  }
  if (stage === 'drafting') {
    return 'Drafting';
  }
  if (stage === 'ready') {
    return 'Waiting for your yes';
  }
  return 'Sent';
}

function sendLabelOf(stage: DraftStage) {
  if (stage === 'sent') {
    return 'Sent';
  }
  return 'Send reply';
}

function waitOf(stage: DraftStage) {
  if (stage === 'reading') {
    return READING_MS;
  }
  if (stage === 'drafting') {
    return DRAFT_MS;
  }
  return null;
}

function nextStageOf(stage: DraftStage): DraftStage {
  if (stage === 'reading') {
    return 'drafting';
  }
  return 'ready';
}

type DraftBodyProps = {
  stage: DraftStage;
  round: number;
  isActive: boolean;
};

function DraftBody({ stage, round, isActive }: DraftBodyProps) {
  if (stage === 'reading') {
    return (
      <p className='text-sm leading-relaxed text-pretty'>
        <StreamedWords words={DRAFT_WORDS} shown={0} isStreaming />
      </p>
    );
  }
  const isStreaming = stage === 'drafting';

  return (
    <p className='text-sm leading-relaxed text-pretty'>
      <StreamedText
        key={round}
        text={DRAFT_REPLY}
        isStreaming={isStreaming}
        isActive={isActive}
        wordMs={WORD_MS}
      />
    </p>
  );
}

export function DraftDemo() {
  const [stage, setStage] = useState<DraftStage>('reading');
  const [round, setRound] = useState(0);
  const shouldReduceMotion = usePrefersReducedMotion();
  const { pressed, press } = usePress<'send'>();
  const steps = [
    { after: SEND_AFTER_MS, run: () => press('send') },
    { after: 240, run: () => setStage('sent') },
    { after: 3200, run: hold },
  ];
  const { ref, isInView } = useAutoplay(steps, {
    loopAfter: 1000,
    onReset: () => setStage('reading'),
  });
  const canSend = stage === 'ready';
  const canRedraft = stage === 'ready' || stage === 'sent';
  const statusWord = statusWordOf(stage);
  const sendLabel = sendLabelOf(stage);
  const hasSent = stage === 'sent';

  useKeptHeight(ref);
  useRestingState<DraftStage>(shouldReduceMotion, 'ready', setStage);

  useEffect(() => {
    const wait = waitOf(stage);
    if (wait === null || !isInView) {
      return;
    }
    const next = nextStageOf(stage);
    const timer = setTimeout(() => setStage(next), wait);
    return () => clearTimeout(timer);
  }, [stage, round, isInView]);

  function redraft() {
    setRound((current) => current + 1);
    setStage('drafting');
  }

  return (
    <div
      ref={ref}
      className='bg-card hairline-ring ring-border flex w-full max-w-sm flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]'
    >
      <div className='bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-3'>
        <div className='flex items-center gap-2.5'>
          <Avatar
            className='size-6'
            seed={INCOMING.from}
            role='img'
            aria-label={INCOMING.from}
          />
          <p className='text-[13px] font-medium'>{INCOMING.from}</p>
          <p className='text-muted-foreground ms-auto text-xs tabular-nums'>
            {INCOMING.time}
          </p>
        </div>
        <p className='text-[13px] leading-relaxed text-pretty'>
          {INCOMING.text}
        </p>
      </div>
      <div className='flex flex-col gap-2 px-1'>
        <div className='flex items-center gap-2'>
          <MeshTile seed={ASSISTANT.name} size='md' />
          <p className='text-muted-foreground text-xs font-medium'>
            Draft reply
          </p>
          <p
            aria-live='polite'
            className='text-muted-foreground ms-auto flex items-center gap-1.5 text-xs'
          >
            {hasSent && <DrawnCheck tone='success' entrance='pop' />}
            <Swap swapKey={statusWord}>{statusWord}</Swap>
          </p>
        </div>
        <DraftBody stage={stage} round={round} isActive={isInView} />
      </div>
      <div className='flex items-center justify-end gap-2'>
        <Button
          type='button'
          variant='ghost'
          size='sm'
          disabled={!canRedraft}
          focusableWhenDisabled
          onClick={redraft}
        >
          <RotateCcwIcon />
          Redraft
        </Button>
        <Button
          type='button'
          size='sm'
          disabled={!canSend}
          focusableWhenDisabled
          onClick={() => setStage('sent')}
          className={pressedSolidOf(pressed === 'send')}
        >
          <Swap swapKey={sendLabel}>{sendLabel}</Swap>
        </Button>
      </div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { type Commitment, COMMITMENTS, NEW_COMMITMENT } from './data';
import { useRestingState } from './use-resting-state';

type NotesState = {
  hasNew: boolean;
  doneIds: string[];
};

const FIRST: NotesState = { hasNew: false, doneIds: [] };

const RESTING: NotesState = {
  hasNew: true,
  doneIds: ['quote', 'contract'],
};

function listOf(state: NotesState) {
  if (state.hasNew) {
    return [NEW_COMMITMENT, ...COMMITMENTS];
  }
  return COMMITMENTS;
}

function isDoneIn(state: NotesState, id: string) {
  return state.doneIds.includes(id);
}

function toggled(state: NotesState, id: string): NotesState {
  if (isDoneIn(state, id)) {
    const remaining = state.doneIds.filter((doneId) => doneId !== id);
    return { ...state, doneIds: remaining };
  }
  return { ...state, doneIds: [...state.doneIds, id] };
}

function openCountOf(state: NotesState) {
  const list = listOf(state);
  const open = list.filter((item) => !isDoneIn(state, item.id));
  return open.length;
}

type PromiseRowProps = {
  item: Commitment;
  isDone: boolean;
  onToggle: () => void;
};

function PromiseRow({ item, isDone, onToggle }: PromiseRowProps) {
  return (
    <div className='flex items-center gap-3 px-2.5 py-2.5'>
      <button
        type='button'
        role='checkbox'
        aria-checked={isDone}
        aria-label={`Mark "${item.text}" as done`}
        onClick={onToggle}
        className='focus-visible:ring-ring relative flex size-5 shrink-0 items-center justify-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-offset-2'
      >
        <span
          aria-hidden='true'
          className='hairline-ring ring-foreground/25 absolute size-[18px] rounded-full'
        />
        <AnimatePresence initial={false}>
          {isDone && (
            <DrawnCheck key='check' tone='success' className='absolute' />
          )}
        </AnimatePresence>
      </button>
      <span
        className={cn(
          'min-w-0 flex-1 truncate text-[13px] transition-colors duration-200',
          isDone && 'text-muted-foreground line-through'
        )}
      >
        {item.text}
      </span>
      <Badge variant='secondary' className='text-muted-foreground'>
        {item.due}
      </Badge>
    </div>
  );
}

export function NotesDemo() {
  const [state, setState] = useState<NotesState>(FIRST);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);
  const steps = [
    { after: 1500, run: () => setState({ ...FIRST, hasNew: true }) },
    {
      after: 1700,
      run: () => setState((current) => toggled(current, 'quote')),
    },
    {
      after: 1500,
      run: () => setState((current) => toggled(current, 'contract')),
    },
    { after: 3400, run: hold },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: 1200,
    onReset: () => setState(FIRST),
  });
  const list = listOf(state);
  const openCount = openCountOf(state);

  useKeptHeight(ref);
  useRestingState<NotesState>(shouldReduceMotion, RESTING, setState);

  return (
    <div
      ref={ref}
      className='bg-card hairline-ring ring-border flex w-full max-w-sm flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]'
    >
      <div className='flex items-center justify-between gap-3 px-1 pt-1'>
        <p className='text-muted-foreground text-xs font-medium'>
          Promises this week
        </p>
        <p
          aria-live='polite'
          className='text-muted-foreground flex items-center gap-1 text-xs'
        >
          <MotionNumber
            value={openCount}
            className='text-foreground font-medium'
          />
          open
        </p>
      </div>
      <ul className='bg-foreground/[0.04] flex flex-col rounded-lg'>
        <AnimatePresence initial={false}>
          {list.map((item) => (
            <motion.li key={item.id} {...presence} className='overflow-hidden'>
              <PromiseRow
                item={item}
                isDone={isDoneIn(state, item.id)}
                onToggle={() =>
                  setState((current) => toggled(current, item.id))
                }
              />
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
}

'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';
import { StatusOrb, type StatusOrbTone } from '@/registry/ndeko/ui/status-orb';

import {
  DAY_EVENTS,
  DAY_HOURS,
  DAY_START_HOUR,
  type DayEvent,
  MOVED_REVIEW_START,
  NEW_EVENT,
  PLAN_NOTES,
} from './data';
import { useRestingState } from './use-resting-state';

type PlanStage = 'calm' | 'clash' | 'moved';

const HOUR_LABELS = Array.from(
  { length: DAY_HOURS },
  (_, index) => `${DAY_START_HOUR + index}:00`
);

const BLOCK =
  'absolute flex flex-col justify-center rounded-lg px-2.5 text-xs transition-[translate,opacity] duration-500 ease-(--ease-out-strong) translate-y-[calc(var(--start)*3rem+0.125rem)] h-[calc(var(--hours)*3rem-0.25rem)]';

const BLOCK_ARRIVAL =
  'starting:opacity-0 motion-safe:starting:translate-x-6 motion-safe:starting:translate-y-[calc(var(--start)*3rem+0.125rem)]';

type BlockStyle = React.CSSProperties & {
  '--start': number;
  '--hours': number;
};

function blockStyleOf(start: number, hours: number): BlockStyle {
  return { '--start': start, '--hours': hours };
}

function startOf(event: DayEvent, stage: PlanStage) {
  const isReview = event.id === 'review';
  const hasMoved = stage === 'moved';
  if (isReview && hasMoved) {
    return MOVED_REVIEW_START;
  }
  return event.start;
}

function toneOfStage(stage: PlanStage): StatusOrbTone {
  if (stage === 'clash') {
    return 'warning';
  }
  return 'success';
}

function noteOfStage(stage: PlanStage) {
  if (stage === 'clash') {
    return PLAN_NOTES.overlap;
  }
  if (stage === 'moved') {
    return PLAN_NOTES.moved;
  }
  return PLAN_NOTES.calm;
}

function isClashing(event: DayEvent, stage: PlanStage) {
  const isReview = event.id === 'review';
  return isReview && stage === 'clash';
}

function EventBlock({ event, stage }: { event: DayEvent; stage: PlanStage }) {
  const start = startOf(event, stage);
  const hasClash = isClashing(event, stage);

  return (
    <li
      style={blockStyleOf(start, event.hours)}
      className={cn(
        BLOCK,
        'bg-foreground/[0.06] inset-x-0',
        hasClash && 'bg-warning/10 text-warning-foreground'
      )}
    >
      <span className='truncate font-medium'>{event.title}</span>
      <span className='text-muted-foreground tabular-nums'>
        {event.timeLabel}
      </span>
    </li>
  );
}

function NewEventBlock() {
  return (
    <li
      style={blockStyleOf(NEW_EVENT.start, NEW_EVENT.hours)}
      className={cn(
        BLOCK,
        BLOCK_ARRIVAL,
        'bg-info/10 text-info-foreground start-6 end-0 z-10 shadow-[0_1px_2px_rgb(0_0_0/0.06)]'
      )}
    >
      <span className='truncate font-medium'>{NEW_EVENT.title}</span>
      <span className='tabular-nums'>{NEW_EVENT.timeLabel}</span>
    </li>
  );
}

const STEPS_DELAYS = { clash: 1500, moved: 1900 };

export function PlanDemo() {
  const [stage, setStage] = useState<PlanStage>('calm');
  const steps = [
    { after: STEPS_DELAYS.clash, run: () => setStage('clash') },
    { after: STEPS_DELAYS.moved, run: () => setStage('moved') },
    { after: 3600, run: hold },
  ];
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 1200,
    onReset: () => setStage('calm'),
  });
  useRestingState<PlanStage>(!isAutoplaying, 'moved', setStage);
  const hasNewEvent = stage !== 'calm';
  const note = noteOfStage(stage);
  const tone = toneOfStage(stage);
  const hasClash = stage === 'clash';

  useKeptHeight(ref);

  return (
    <div
      ref={ref}
      role='img'
      aria-label='A sample day where a new event lands on top of another one and Murmura moves the one that can move'
      className='bg-card hairline-ring ring-border flex w-full max-w-sm flex-col gap-3 rounded-xl p-3 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]'
    >
      <div className='flex items-center justify-between gap-3 px-1 pt-1'>
        <p className='text-muted-foreground text-xs font-medium'>Thursday</p>
        {hasClash && <Chip color='var(--warning)'>Overlap</Chip>}
      </div>
      <div className='flex gap-3'>
        <ol className='text-muted-foreground flex w-9 shrink-0 flex-col text-xs tabular-nums'>
          {HOUR_LABELS.map((label) => (
            <li key={label} className='h-12'>
              {label}
            </li>
          ))}
        </ol>
        <ul
          style={{ height: `${DAY_HOURS * 3}rem` }}
          className='relative min-w-0 flex-1'
        >
          {DAY_EVENTS.map((event) => (
            <EventBlock key={event.id} event={event} stage={stage} />
          ))}
          {hasNewEvent && <NewEventBlock />}
        </ul>
      </div>
      <p className='bg-foreground/[0.04] flex min-h-10 items-center gap-2.5 rounded-lg px-2.5 py-2 text-[13px]'>
        <StatusOrb tone={tone} size='sm' />
        <Swap swapKey={note} className='min-w-0 text-start'>
          {note}
        </Swap>
      </p>
    </div>
  );
}

/** A backing store above two device pixels costs four times the fill for a picture nobody sees sharper. */
const MAX_PIXEL_RATIO = 2;

const FRAMES_PER_SECOND = 24;

const FRAME_MS = 1000 / FRAMES_PER_SECOND;

/** The timer between two frames ends this long before the next one is due, so the frame lands on the refresh that is due. */
const REFRESH_LEAD_MS = 5;

const TIMER_MS = FRAME_MS - REFRESH_LEAD_MS;

/** A frame that comes late, after a long task, moves the picture no further than this long would. */
const MAX_STEP_S = 0.05;

const THEME_WATCH = {
  attributes: true,
  attributeFilter: ['class', 'data-theme'],
};

const DARK_SCHEME = '(prefers-color-scheme: dark)';

export const NEXT_FRAME = 0;

export const AT_REST = Number.POSITIVE_INFINITY;

export type Surface = {
  canvas: HTMLCanvasElement;
  pen: CanvasRenderingContext2D;
  width: number;
  height: number;
  pixelRatio: number;
};

export type Inks = {
  hue: string;
  neutral: string;
};

export type Scene = {
  ink: (inks: Inks) => void;
  fit: (surface: Surface, isStill: boolean) => void;
  draw: (surface: Surface) => void;
  step: (surface: Surface, seconds: number) => number;
};

export type Stage = {
  dispose: () => void;
};

export type StageOptions = {
  isStill: boolean;
};

function pixelRatioOf() {
  const screenRatio = window.devicePixelRatio || 1;
  return Math.min(screenRatio, MAX_PIXEL_RATIO);
}

function createSurface(canvas: HTMLCanvasElement): Surface | null {
  const pen = canvas.getContext('2d');
  if (!pen) {
    return null;
  }
  return { canvas, pen, width: 0, height: 0, pixelRatio: 1 };
}

function fitSurface(surface: Surface) {
  const { canvas, pen } = surface;
  const pixelRatio = pixelRatioOf();
  const width = canvas.clientWidth;
  const height = canvas.clientHeight;
  surface.width = width;
  surface.height = height;
  surface.pixelRatio = pixelRatio;
  canvas.width = Math.round(width * pixelRatio);
  canvas.height = Math.round(height * pixelRatio);
  pen.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
}

function isFitted(surface: Surface) {
  const { canvas } = surface;
  const hasWidth = surface.width === canvas.clientWidth;
  const hasHeight = surface.height === canvas.clientHeight;
  const hasRatio = surface.pixelRatio === pixelRatioOf();
  const hasSize = hasWidth && hasHeight;
  return hasSize && hasRatio;
}

export function wipeSurface(surface: Surface) {
  surface.pen.globalAlpha = 1;
  surface.pen.clearRect(0, 0, surface.width, surface.height);
}

/**
 * A canvas cannot take a colour from a class, so it reads its colours from its own computed style,
 * where the browser has already resolved the tokens for the current theme: the hue rides on
 * `color`, the neutral on `text-decoration-color`, which paints nothing on a canvas.
 */
function inksOf(canvas: HTMLCanvasElement): Inks {
  const style = getComputedStyle(canvas);
  return { hue: style.color, neutral: style.textDecorationColor };
}

function hasSameInks(first: Inks, second: Inks) {
  const hasSameHue = first.hue === second.hue;
  const hasSameNeutral = first.neutral === second.neutral;
  return hasSameHue && hasSameNeutral;
}

function densityQueryOf() {
  return `(resolution: ${window.devicePixelRatio}dppx)`;
}

function watchSurface(
  canvas: HTMLCanvasElement,
  onResize: () => void,
  onTheme: () => void
) {
  const sizeObserver = new ResizeObserver(() => onResize());
  const themeObserver = new MutationObserver(() => onTheme());
  const scheme = window.matchMedia(DARK_SCHEME);
  let density = window.matchMedia(densityQueryOf());

  function onScheme() {
    onTheme();
  }

  /** The query names one density: once the screen has left it, a new query watches the next one. */
  function onDensity() {
    density.removeEventListener('change', onDensity);
    density = window.matchMedia(densityQueryOf());
    density.addEventListener('change', onDensity);
    onResize();
  }

  sizeObserver.observe(canvas);
  themeObserver.observe(document.documentElement, THEME_WATCH);
  themeObserver.observe(document.body, THEME_WATCH);
  scheme.addEventListener('change', onScheme);
  density.addEventListener('change', onDensity);

  return () => {
    sizeObserver.disconnect();
    themeObserver.disconnect();
    scheme.removeEventListener('change', onScheme);
    density.removeEventListener('change', onDensity);
  };
}

function watchShowing(
  element: Element,
  onChange: (isShowing: boolean) => void
) {
  let isOnScreen = false;
  let wasShowing = false;

  function report() {
    const isTabShown = document.visibilityState === 'visible';
    const isShowing = isOnScreen && isTabShown;
    if (isShowing === wasShowing) {
      return;
    }
    wasShowing = isShowing;
    onChange(isShowing);
  }

  function onCrossing(entries: IntersectionObserverEntry[]) {
    const latest = entries.at(-1);
    if (!latest) {
      return;
    }
    isOnScreen = latest.isIntersecting;
    report();
  }

  const observer = new IntersectionObserver(onCrossing);
  observer.observe(element);
  document.addEventListener('visibilitychange', report);

  return () => {
    observer.disconnect();
    document.removeEventListener('visibilitychange', report);
  };
}

type FrameHandler = (seconds: number) => number;

type FrameLoop = {
  start: () => void;
  stop: () => void;
  wake: () => void;
};

/**
 * Frames at twenty-four a second at most. Between two frames there is one timer and no animation
 * frame, so a fast screen does not run extra rounds of main-thread work. Stopped or at rest, the
 * loop holds no timer and asks for no frame.
 */
function createFrameLoop(onFrame: FrameHandler): FrameLoop {
  let frame = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let isStarted = false;
  let lastFrameAt = 0;

  function clearPending() {
    cancelAnimationFrame(frame);
    clearTimeout(timer);
    frame = 0;
    timer = undefined;
  }

  function askForFrame() {
    timer = undefined;
    frame = requestAnimationFrame(tick);
  }

  function schedule(wait: number) {
    clearPending();
    const now = performance.now();
    const sinceFrame = now - lastFrameAt;
    const untilCap = TIMER_MS - sinceFrame;
    const delay = Math.max(wait, untilCap);
    if (delay <= 0) {
      askForFrame();
      return;
    }
    timer = setTimeout(askForFrame, delay);
  }

  function tick(now: number) {
    frame = 0;
    const elapsedMs = now - lastFrameAt;
    const elapsed = elapsedMs / 1000;
    const forward = Math.max(0, elapsed);
    const seconds = Math.min(forward, MAX_STEP_S);
    lastFrameAt = now;
    const wait = onFrame(seconds);
    const isResting = wait === AT_REST;
    if (isResting || !isStarted) {
      return;
    }
    schedule(wait);
  }

  function start() {
    if (isStarted) {
      return;
    }
    isStarted = true;
    lastFrameAt = performance.now() - FRAME_MS;
    schedule(NEXT_FRAME);
  }

  function stop() {
    isStarted = false;
    clearPending();
  }

  function wake() {
    const isFrameComing = frame !== 0;
    if (!isStarted || isFrameComing) {
      return;
    }
    schedule(NEXT_FRAME);
  }

  return { start, stop, wake };
}

function stageOf(
  surface: Surface,
  scene: Scene,
  { isStill }: StageOptions
): Stage {
  const { canvas } = surface;
  let inks = inksOf(canvas);

  const loop = createFrameLoop((seconds) => scene.step(surface, seconds));

  function lay() {
    fitSurface(surface);
    scene.fit(surface, isStill);
    scene.draw(surface);
  }

  function onResize() {
    if (isFitted(surface)) {
      return;
    }
    lay();
    loop.wake();
  }

  function onTheme() {
    const latest = inksOf(canvas);
    if (hasSameInks(inks, latest)) {
      return;
    }
    inks = latest;
    scene.ink(inks);
    scene.draw(surface);
    loop.wake();
  }

  function onScroll() {
    loop.wake();
  }

  function onShowing(isShowing: boolean) {
    if (isShowing && !isStill) {
      window.addEventListener('scroll', onScroll, { passive: true });
      loop.start();
      return;
    }
    window.removeEventListener('scroll', onScroll);
    loop.stop();
  }

  scene.ink(inks);
  lay();
  const stopSurface = watchSurface(canvas, onResize, onTheme);
  const stopShowing = watchShowing(canvas, onShowing);

  return {
    dispose() {
      stopShowing();
      stopSurface();
      window.removeEventListener('scroll', onScroll);
      loop.stop();
    },
  };
}

export function mountStage(
  canvas: HTMLCanvasElement,
  scene: Scene,
  options: StageOptions
) {
  const surface = createSurface(canvas);
  if (!surface) {
    return null;
  }
  return stageOf(surface, scene, options);
}

